#!/usr/bin/env bash
# ============================================================
# setup-chatlog.sh — 全プロジェクト自動チャットログ インストーラ（冪等）
#   Claude Code の「環境セットアップ（起動スクリプト）」に登録すると、
#   以後どのリポジトリ（新規/既存問わず）でも会話が自動記録される。
#   何度実行しても安全。
# ============================================================
set -e
NODE_BIN="$(command -v node || echo /opt/node22/bin/node)"
mkdir -p "$HOME/.claude/hooks"

# ロガー本体を設置（base64 埋め込み＝エスケープ事故なし）
base64 -d > "$HOME/.claude/hooks/chatlog-record.js" <<'B64EOF'

B64EOF

# Stop フックを ~/.claude/settings.json へ冪等マージ
"$NODE_BIN" - <<'NODEEOF'
const fs=require('fs'),os=require('os'),path=require('path');
const f=path.join(os.homedir(),'.claude','settings.json');
let s={}; try{s=JSON.parse(fs.readFileSync(f,'utf8'))}catch{}
s.hooks=s.hooks||{}; s.hooks.Stop=Array.isArray(s.hooks.Stop)?s.hooks.Stop:[];
const cmd="node ~/.claude/hooks/chatlog-record.js 2>/dev/null || /opt/node22/bin/node ~/.claude/hooks/chatlog-record.js 2>/dev/null || true";
const present=JSON.stringify(s.hooks.Stop).includes('chatlog-record.js');
if(!present) s.hooks.Stop.push({hooks:[{type:'command',command:cmd}]});
fs.writeFileSync(f, JSON.stringify(s,null,2)+'\n');
console.log(present?'[chatlog] already installed (no change)':'[chatlog] installed');
NODEEOF

echo "[chatlog] done. 反映は /hooks を一度開く（または再起動）。以後 logs/<project>/ に自動記録。"
